try {
    int result = 10 / 0;
    System.out.println("Result: " + result);
} catch (ArithmeticException e) {
    System.out.println("Cannot divide by zero.");
}
System.out.println("Program continues normally.");

static void level3() {
    System.out.println("level3 start");
    int x = 10 / 0;
    System.out.println("level3 end");
}

static void level2() {
    System.out.println("level2 start");
    level3();
    System.out.println("level2 end");
}

try {
    level2();
} catch (ArithmeticException e) {
    System.out.println("caught in main");
}

try {
    int[] numbers = {1, 2, 3};
    System.out.println(numbers[10]);
} catch (ArrayIndexOutOfBoundsException e) {
    System.out.println("Caught: invalid index.");
} finally {
    System.out.println("This always runs.");
}

static int withFinally() {
    try {
        return 1;
    } finally {
        System.out.println("cleanup");
    }
}

System.out.println(withFinally());
